use crate::aap::caps::state_read;

struct Node;

/// Keys tried, in order, in the read-only `subscriptions` store.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

/// Accepts either a JSON array of strings, or plain text with one URL per
/// line (commas and whitespace also separate; `#` starts a comment line).
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_string_array(trimmed).unwrap_or_default()
    } else {
        trimmed
            .lines()
            .map(str::trim)
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .flat_map(|l| l.split(|c: char| c == ',' || c.is_whitespace()))
            .map(|s| s.trim().to_string())
            .collect()
    };

    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let c = c.trim().to_string();
        if c.is_empty() {
            continue;
        }
        if !(c.starts_with("http://") || c.starts_with("https://")) {
            continue;
        }
        if !out.contains(&c) {
            out.push(c);
        }
    }
    out
}

/// Minimal parser for a JSON array whose elements are strings.
/// Non-string elements cause the whole parse to fail (returns None).
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    let mut out = Vec::new();

    skip_ws(&chars, &mut i);
    if chars.get(i) != Some(&'[') {
        return None;
    }
    i += 1;
    skip_ws(&chars, &mut i);
    if chars.get(i) == Some(&']') {
        return Some(out);
    }
    loop {
        skip_ws(&chars, &mut i);
        out.push(parse_json_string(&chars, &mut i)?);
        skip_ws(&chars, &mut i);
        match chars.get(i) {
            Some(',') => {
                i += 1;
            }
            Some(']') => {
                i += 1;
                break;
            }
            _ => return None,
        }
    }
    skip_ws(&chars, &mut i);
    if i != chars.len() {
        return None;
    }
    Some(out)
}

fn skip_ws(chars: &[char], i: &mut usize) {
    while let Some(c) = chars.get(*i) {
        if c.is_whitespace() {
            *i += 1;
        } else {
            break;
        }
    }
}

fn parse_hex4(chars: &[char], i: &mut usize) -> Option<u32> {
    let mut v = 0u32;
    for _ in 0..4 {
        let d = chars.get(*i)?.to_digit(16)?;
        v = v * 16 + d;
        *i += 1;
    }
    Some(v)
}

fn parse_json_string(chars: &[char], i: &mut usize) -> Option<String> {
    if chars.get(*i) != Some(&'"') {
        return None;
    }
    *i += 1;
    let mut s = String::new();
    loop {
        let c = *chars.get(*i)?;
        *i += 1;
        match c {
            '"' => return Some(s),
            '\\' => {
                let e = *chars.get(*i)?;
                *i += 1;
                match e {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{8}'),
                    'f' => s.push('\u{c}'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let hi = parse_hex4(chars, i)?;
                        let cp = if (0xD800..0xDC00).contains(&hi) {
                            if chars.get(*i) == Some(&'\\') && chars.get(*i + 1) == Some(&'u') {
                                *i += 2;
                                let lo = parse_hex4(chars, i)?;
                                if !(0xDC00..0xE000).contains(&lo) {
                                    return None;
                                }
                                0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                            } else {
                                return None;
                            }
                        } else {
                            hi
                        };
                        s.push(char::from_u32(cp)?);
                    }
                    _ => return None,
                }
            }
            c if (c as u32) < 0x20 => return None,
            c => s.push(c),
        }
    }
}

export!(Node);
